def next_job(jobs):
    if not jobs:
        return None
    return jobs[0]

def buckets(labels):
    groups = {}
    for label in labels:
        first = label[0]
        groups.setdefault(first, []).append(label)
    return groups

def split_header(line):
    name, value = line.split(':', 1)
    return [name.strip(), value.strip()]

def leader(scores):
    ranked = sorted(scores, reverse=True)
    return ranked[0]

def repeat_read(items):
    stream = list(items)
    return [sum(stream), sum(stream)]

def pages(groups):
    result = []
    for group in groups:
        result.extend(group)
    return result

def total_prices(prices):
    amount = 0
    for price in prices:
        amount += price
    return amount

def clock_parts(minutes):
    hours, rest = divmod(minutes, 60)
    return [hours, rest]

def max_debt(values):
    best = values[0]
    for value in values[1:]:
        best = max(best, value)
    return best

def withdraw(balance, amount):
    if amount > balance:
        return balance
    return balance - amount

def first_large(values):
    answer = None
    for item in values:
        if item > 10:
            answer = item
            break
    return answer

def sort_matrix(M):
    result = sorted(M, key=sum)
    return result

def square_nums(nums):
    square_nums = list(map(lambda x: x ** 2, nums))
    return square_nums
